"use strict";(self.webpackChunkdev_knowledge_base=self.webpackChunkdev_knowledge_base||[]).push([[8464],{28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>i});var a=n(96540);const r={},s=a.createContext(r);function o(e){const t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),a.createElement(s.Provider,{value:t},e.children)}},68106:e=>{e.exports=JSON.parse('{"permalink":"/en/blog/2026/04/02/paper-is-dead-hardcore-research","source":"@site/i18n/en/docusaurus-plugin-content-blog/2026-04-02-paper-is-dead-hardcore-research.md","title":"Paper Is Dead, Hardcore Research Must Rise","description":"Notes from Professor Qiang Xu\'s talk on research paradigms in the AI era, reflecting on real deliverables beyond papers, Agent governance, and research judgment.","date":"2026-04-02T00:00:00.000Z","tags":[{"inline":false,"label":"Research","permalink":"/en/blog/tags/research"}],"readingTime":11.26,"hasTruncateMarker":true,"authors":[{"name":"DingZhiyu","title":"Southwest Petroleum University","url":"https://nevergpdzy.com","email":"dingzhiyu2004@163.com","socials":{"github":"https://github.com/NeverGpDzy"},"imageURL":"https://oss.nevergpdzy.com/img_for_Typora/6cdbc90753f6f68dda6fc8243b6baef.jpg","key":"DingZhiyu","page":null}],"frontMatter":{"title":"Paper Is Dead, Hardcore Research Must Rise","authors":"DingZhiyu","tags":["research"],"description":"Notes from Professor Qiang Xu\'s talk on research paradigms in the AI era, reflecting on real deliverables beyond papers, Agent governance, and research judgment."},"unlisted":false,"prevItem":{"title":"The Hard Part Of Agents Is Not How Smart The Model Is","permalink":"/en/blog/2026/04/07/agent-harness"},"nextItem":{"title":"Sim Racing, Cooking, And A Little Tipsiness","permalink":"/en/blog/2026/03/20/friends-meet-sim-racing-and-home-dinner"}}')},96098:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>c,frontMatter:()=>o,metadata:()=>a,toc:()=>h});var a=n(68106),r=n(74848),s=n(28453);const o={title:"Paper Is Dead, Hardcore Research Must Rise",authors:"DingZhiyu",tags:["research"],description:"Notes from Professor Qiang Xu's talk on research paradigms in the AI era, reflecting on real deliverables beyond papers, Agent governance, and research judgment."},i="Paper Is Dead, Hardcore Research Must Rise",l={authorsImageUrls:[void 0]},h=[{value:"When Papers Are No Longer The Only Endpoint Of Research",id:"when-papers-are-no-longer-the-only-endpoint-of-research",level:2},{value:"The Stronger Agents Become, The More They Need A Regulatory Kernel",id:"the-stronger-agents-become-the-more-they-need-a-regulatory-kernel",level:2},{value:"AI Levels Techniques, Not Research Ability Itself",id:"ai-levels-techniques-not-research-ability-itself",level:2},{value:"The Q&amp;A Made The Researcher&#39;s &quot;Self-cultivation&quot; Clearer",id:"the-qa-made-the-researchers-self-cultivation-clearer",level:2},{value:"In The AI Era, Education Should Not Mainly Train &quot;People Who Can Solve Problems On Tests&quot;",id:"in-the-ai-era-education-should-not-mainly-train-people-who-can-solve-problems-on-tests",level:2},{value:"Closing",id:"closing",level:2},{value:"Appendix: Original Meeting Notes",id:"appendix-original-meeting-notes",level:2},{value:"Summary",id:"summary",level:3},{value:"1. Reshaping Research Paradigms And Deliverables",id:"1-reshaping-research-paradigms-and-deliverables",level:3},{value:"2. Regulatory Kernel In The Agent Era: OS System",id:"2-regulatory-kernel-in-the-agent-era-os-system",level:3},{value:"3. Key Issues And Views",id:"3-key-issues-and-views",level:3},{value:"To-do",id:"to-do",level:3},{value:"Q&amp;A Notes",id:"qa-notes",level:3}];function d(e){const t={code:"code",em:"em",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:["On ",(0,r.jsx)(t.code,{children:"Thursday, April 2, 2026, 19:30 - 21:00"}),", I attended a talk by Professor Qiang Xu from the Department of Computer Science and Engineering at The Chinese University of Hong Kong. The title was sharp: ",(0,r.jsx)(t.em,{children:"Paper Is Dead, Hardcore Research Must Rise: Self-cultivation For Researchers In The AI Era"}),"."]}),"\n",(0,r.jsx)(t.p,{children:'"Paper is dead" is of course a deliberately provocative phrase. But what it really pierces is not whether papers have value, but a deeper question: when AI is systematically rewriting the research workflow, what should researchers use to prove their value? And what should count as the real deliverable of future research?'}),"\n",(0,r.jsx)(t.p,{children:"After listening to the full talk, my strongest feeling was that the AI era has not made research easier. Instead, it has made the question of what truly counts as research much clearer."}),"\n",(0,r.jsx)(t.h2,{id:"when-papers-are-no-longer-the-only-endpoint-of-research",children:"When Papers Are No Longer The Only Endpoint Of Research"}),"\n",(0,r.jsx)(t.p,{children:'For a long time, papers were almost the most typical representation of research output. Whether a study "stood" often depended on whether it could be written into a paper and published at a sufficiently good conference or journal. Papers are of course important. But if the endpoint of research is completely equated with publication, that paradigm is now being rapidly challenged by the AI era.'}),"\n",(0,r.jsx)(t.p,{children:"Professor Xu repeatedly emphasized that research outputs with real vitality in the future should not only be papers. They should also include tools, APIs, benchmarks, ground truth, and other infrastructure that Agents can call. In other words, the value of research is no longer reflected only in citations. It is also reflected in whether the work truly solves real needs, whether it can be called, reused, extended, and eventually enter a long-running technical ecosystem."}),"\n",(0,r.jsx)(t.p,{children:'This is, in essence, pulling research back from "writing it out" to "building it out."'}),"\n",(0,r.jsxs)(t.p,{children:["Around this point, the talk also mentioned an evaluation framework worth remembering: ",(0,r.jsx)(t.code,{children:"ROSE"}),'. A good research work should solve a real need, be original, be significant, and retain a certain elegance. Compared with asking "where was this paper published," this standard is obviously harder, but also closer to research itself.']}),"\n",(0,r.jsx)(t.p,{children:"Because truly good research does not necessarily stop at a paper. It is more likely to continue becoming tools, systems, and methods, and to keep living inside later work."}),"\n",(0,r.jsx)(t.h2,{id:"the-stronger-agents-become-the-more-they-need-a-regulatory-kernel",children:"The Stronger Agents Become, The More They Need A Regulatory Kernel"}),"\n",(0,r.jsx)(t.p,{children:"The second main thread of the talk was system governance in the Agent era."}),"\n",(0,r.jsx)(t.p,{children:"Today, when many people talk about Agents, they focus more on the expanding boundary of capability: Agents can understand tasks, decompose workflows, call tools, and in some scenarios even show signs of near-autonomous action. But the more this is true, the harder it is to avoid one question: if Agents become increasingly powerful, who ensures that their final behavior remains safe, reliable, and controllable?"}),"\n",(0,r.jsx)(t.p,{children:'Professor Xu\'s answer was a "regulatory kernel."'}),"\n",(0,r.jsx)(t.p,{children:"This concept is very interesting. It is not simply adding a few rules to a model. Rather, it tries to build a constraint structure between the large language model and the external world, somewhat like an operating system. The large model is responsible for open-ended semantic output, for proposing plans and creating possibilities. The regulatory kernel maps those open semantics into deterministic instructions that can be inspected, constrained, and executed, and then uses boundary checks and rule interception to ensure that the system does not cross lines or lose control."}),"\n",(0,r.jsxs)(t.p,{children:["In one sentence: the ",(0,r.jsx)(t.code,{children:"LLM"})," thinks; the kernel guards."]}),"\n",(0,r.jsx)(t.p,{children:'Behind this lies a crucial cognitive shift. A mature Agent system cannot be built only by stacking "smarter" models. It must have a verifiable and governable underlying mechanism. System design in the AI era is not only a question of capability. It is also a question of boundaries.'}),"\n",(0,r.jsx)(t.h2,{id:"ai-levels-techniques-not-research-ability-itself",children:"AI Levels Techniques, Not Research Ability Itself"}),"\n",(0,r.jsx)(t.p,{children:'The point I agreed with most in the entire talk was that it did not treat AI simply as an "efficiency tool." It went further and asked: when tools become stronger and stronger, what remains irreplaceable in a researcher?'}),"\n",(0,r.jsx)(t.p,{children:'Professor Xu\'s judgment was clear: AI will indeed flatten many differences at the skill level, but it will not flatten research ability itself. What automation more easily replaces is repetitive labor, low-level "paper-churning," and procedural work built only on proficiency. What remains difficult to replace is insight into problems, judgment about directions, the ability to distinguish reliable information from falsehood, and the ability to move a vague problem toward a verifiable result.'}),"\n",(0,r.jsx)(t.p,{children:"This means that research training in the AI era has changed."}),"\n",(0,r.jsx)(t.p,{children:'In the future, more important than "can you use tools" will be: can you propose a question worth studying? Can you communicate with AI at a high level? Can you judge which results are genuinely effective and which are merely hallucinations that look like answers? Can you push a piece of work from an idea into an outcome that can truly be reused, communicated, and deployed?'}),"\n",(0,r.jsx)(t.p,{children:"The tools are getting stronger, but the abilities that decide the ceiling are becoming more fundamental."}),"\n",(0,r.jsx)(t.h2,{id:"the-qa-made-the-researchers-self-cultivation-clearer",children:'The Q&A Made The Researcher\'s "Self-cultivation" Clearer'}),"\n",(0,r.jsx)(t.p,{children:"Several points from the Q&A after the talk are worth recording separately."}),"\n",(0,r.jsx)(t.p,{children:"Someone asked whether AI would make the gap between people larger, especially whether those already good at organizing, judging, and leading would pull further ahead with AI support."}),"\n",(0,r.jsx)(t.p,{children:"Professor Xu's answer was not pessimistic. He did not think research ability would become permanently locked in the hands of a few \"naturally gifted\" people. Large models may well amplify efficiency gaps. But research thinking itself can be trained. How to sense the value of a problem, how to judge whether information is reliable, and how to organize one's research process are not mysterious talents that cannot be learned. They are abilities that can be built through long-term training."}),"\n",(0,r.jsx)(t.p,{children:'He also mentioned that when reading papers, the most important thing is not only to see what conclusion the authors reached, but to ask: how did they get onto this path? What a mature researcher truly needs to cultivate is not only a store of knowledge, but research taste and judgment. You do not only need to "understand a paper." You need to see how a problem was discovered, defined, advanced, and solved.'}),"\n",(0,r.jsx)(t.p,{children:"This is very important. AI can help you summarize papers faster, extract information, and generate ideas. But if you lack judgment, you can easily be led around by content that is fluent on the surface but empty underneath. The stronger the tools become, the scarcer judgment becomes."}),"\n",(0,r.jsx)(t.h2,{id:"in-the-ai-era-education-should-not-mainly-train-people-who-can-solve-problems-on-tests",children:'In The AI Era, Education Should Not Mainly Train "People Who Can Solve Problems On Tests"'}),"\n",(0,r.jsx)(t.p,{children:"The talk also included a discussion about education that left a deep impression on me."}),"\n",(0,r.jsx)(t.p,{children:"With the help of AI, knowledge acquisition and skill learning will become increasingly democratized. Many things that once required long accumulation are now becoming easier to reach and easier to call upon. But this does not mean education will become lighter. On the contrary, it may become harder."}),"\n",(0,r.jsx)(t.p,{children:"Because when knowledge itself becomes easier to obtain, what becomes scarce is no longer how much content you remember, but how you judge what is worth learning, what is worth doing, and what is worth believing. What truly matters in the future may not be only teaching students to master knowledge, but cultivating judgment, the ability to choose, critical thinking, and the ability to form a sense of problems around real interests."}),"\n",(0,r.jsx)(t.p,{children:"To put it more directly, AI can become an executor, but only if you first are a person with a sense of direction. If someone has no problem consciousness, stronger tools will only let them spin in place faster."}),"\n",(0,r.jsx)(t.h2,{id:"closing",children:"Closing"}),"\n",(0,r.jsx)(t.p,{children:'So what "Paper is dead" really means is not that papers are useless, but that the era in which papers alone serve as the endpoint of research is ending.'}),"\n",(0,r.jsx)(t.p,{children:'Real "hardcore research" in the AI era asks researchers, on one hand, to produce outputs closer to real-world needs, leaving deliverables that can be reused, called, and incorporated into systems. On the other hand, it also asks researchers to cultivate again those most basic and most crucial abilities: problem consciousness, judgment, research taste, and the ability to work with new tools.'}),"\n",(0,r.jsx)(t.p,{children:"The tool revolution has already happened. What will really decide how far a researcher can go next may not be whether they can use AI, but whether, in the AI era, they can still see which problems are truly worth solving."}),"\n",(0,r.jsx)(t.h2,{id:"appendix-original-meeting-notes",children:"Appendix: Original Meeting Notes"}),"\n",(0,r.jsx)(t.p,{children:"The following preserves my note-style record from the talk for reference."}),"\n",(0,r.jsx)(t.h3,{id:"summary",children:"Summary"}),"\n",(0,r.jsx)(t.p,{children:"This session centered on changes to research paradigms in the AI era. It discussed the reshaping of research deliverables, the regulatory kernel in the Agent era, and core questions around research value, AI tool use, and educational models."}),"\n",(0,r.jsx)(t.h3,{id:"1-reshaping-research-paradigms-and-deliverables",children:"1. Reshaping Research Paradigms And Deliverables"}),"\n",(0,r.jsx)(t.p,{children:"The core value of research should not be limited to paper publication and citations. It should also be reflected in whether the work can be called by AI Agents and generate real social impact."}),"\n",(0,r.jsx)(t.p,{children:"Future research deliverables should include infrastructure such as tools, APIs, benchmarks, or ground truth that Agents can call, ensuring the long-term vitality and ecological position of the work."}),"\n",(0,r.jsx)(t.p,{children:'The "ROSE rule" was proposed as a new standard for evaluating research: solve a real need (R), possess originality (O), have significance (S), and demonstrate elegance (E).'}),"\n",(0,r.jsx)(t.h3,{id:"2-regulatory-kernel-in-the-agent-era-os-system",children:"2. Regulatory Kernel In The Agent Era: OS System"}),"\n",(0,r.jsx)(t.p,{children:'To address uncertainty, uncontrollability, and potential risks in Agent systems, the talk proposed building a "regulatory kernel" (OS) as the Agent\'s "rein."'}),"\n",(0,r.jsx)(t.p,{children:"This kernel maps semantic output from large language models into deterministic instruction sets, combines them with rules for boundary checking and interception, and forms a neuro-symbolic system."}),"\n",(0,r.jsx)(t.p,{children:"The goal is for the LLM to create possibilities and formulate plans, while the regulatory kernel guards the boundaries and ensures safe, reliable execution."}),"\n",(0,r.jsx)(t.h3,{id:"3-key-issues-and-views",children:"3. Key Issues And Views"}),"\n",(0,r.jsx)(t.p,{children:'Research value and "water papers": the value of hardcore research lies in deep insight into problems and real solutions, not simple repetitive labor. Automated "water paper" systems lack cognitive gain, while high-quality research processes themselves benefit personal ability.'}),"\n",(0,r.jsx)(t.p,{children:'Use of AI tools: AI tools such as large models can effectively flatten skill-level gaps among researchers with different capabilities. But core "research thinking," such as how to propose valuable questions, how to communicate effectively with AI, and how to judge truth from falsehood, still requires training and cultivation.'}),"\n",(0,r.jsx)(t.p,{children:"Evolution of education: facing AI's impact on knowledge acquisition, education should shift toward cultivating students' core judgment, critical thinking, and cross-domain integration ability, rather than simply transferring knowledge. The role of the classroom should become guiding students to solve problems and engage in deep exchange."}),"\n",(0,r.jsx)(t.h3,{id:"to-do",children:"To-do"}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsx)(t.li,{children:"Open-source project release"}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Qiang Xu will soon release the regulatory kernel system (OS) developed by his team and invite the community to try it and provide feedback."}),"\n",(0,r.jsx)(t.h3,{id:"qa-notes",children:"Q&A Notes"}),"\n",(0,r.jsx)(t.p,{children:"Liu Weifeng: In the first year or two, my feeling was different from the last two years. AI seemed to flatten the research ability of mid-level and senior people, but recently it feels like the gap has widened. People who can use large AI models well are pulling ahead, and many of them have strong organizational and management talent, abilities they have had since childhood. These abilities let them make better use of AI. This gap seems hard to catch up with and may become fixed. How does Professor Xu view this?"}),"\n",(0,r.jsx)(t.p,{children:"Xu Qiang: I have a different opinion. The Industrial Revolution flattened differences in physical strength, and large models flatten differences in human skills, but I do not think they flatten research ability. The research way of thinking can be trained: how to sense the value of a problem, how to communicate effectively with AI, and how to judge whether information is true or false. If you consciously train research thinking, it will not be flattened by AI. So I deny that research ability in the AI era is strongly tied to leadership and organizational talent. Xu also mentioned in his book that the gap will not necessarily become larger; research has patterns and can be trained."}),"\n",(0,r.jsx)(t.p,{children:"There are too many papers to read, so you must select carefully. When reading papers, the main thing is to consider how the author arrived at this path, not just the research content itself. Improve your research taste and judgment, and then you can improve the efficiency and effectiveness of using AI for research."}),"\n",(0,r.jsx)(t.p,{children:"What kind of model to use: use the best AI tools, and pay for the strongest models to improve yourself."}),"\n",(0,r.jsx)(t.p,{children:"School education: with AI, knowledge and skills become more equalized, but judgment and the ability to choose still belong more strongly to experienced people, such as senior students and teachers."}),"\n",(0,r.jsx)(t.p,{children:"Children's education: every era has its own needs. It should not be viewed through the lens of people like us who carry the strong smell of the old order. Knowledge and skills themselves are becoming more equalized, so education now needs to change in this respect. Children must have things they are interested in and love. If they love something, they will naturally have discoveries, needs, and ideas, and at that point they can use AI to work on them, making AI the worker for their own interests and passions. People with ideas and ability will not be replaced. But if someone has no interests and no ideas, then AI really may replace them to a large extent."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}}}]);